 static Map<String,Object> properties(){var p=new HashMap<String,Object>();String[] names={"artifact-bytes","archive-total-bytes","artifacts","dependencies","graph-depth","json-tokens","json-depth","name-utf16","string-utf16","string-utf8","aggregate-scalars","manifest-bytes","batch-files","fact-rows","fact-edges","canonical-bytes","canonical-depth","canonical-nodes","canonical-string-utf8","canonical-scalars"};long[] values={65536,16777216,64,128,128,2000000,128,255,4194304,4194304,16777216,65536,64,100000,500000,67108864,128,4000000,4194304,16777216};for(int n=0;n<names.length;n++)p.put("processing.bounds."+names[n],values[n]);String[] saved={"utf8","scalars","utf16","copy-bytes","copy-utf16","response-bytes","revision-depth","revision-nodes","tasks"};long[] limits={16777216,16777216,16777216,268435456,134217728,33554432,128,256,256};for(int n=0;n<saved.length;n++)p.put("minutes.bounds."+saved[n],limits[n]);return p;}
 String session(JdbcTemplate j,String actor)throws Exception{if(privateSessions.containsKey(actor))return privateSessions.get(actor);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(java.security.SecureRandom.getSeed(32));sessionSql.set(true);try{assertEquals(1,j.update("INSERT INTO identity_session(token_hash,enterprise_id,session_generation,csrf_token,issued_at,expires_at) SELECT ?,enterprise_id,session_generation,?,UTC_TIMESTAMP(6)-INTERVAL 1 MINUTE,UTC_TIMESTAMP(6)+INTERVAL 1 HOUR FROM enterprise_identity WHERE enterprise_id=? AND status='ACTIVE'",hash(token),"C".repeat(43),actor));privateSessions.put(actor,token);}finally{sessionSql.set(false);}return token;}
 HttpResponse<String> request(String origin,String token,String method,String path,String body,String key)throws Exception {var b=HttpRequest.newBuilder(URI.create(origin+"/api/v1"+path)).timeout(Duration.ofSeconds(15)).header("Cookie",SessionCookies.NAME+"="+token);if(!method.equals("GET")){b.header("Origin","https://task11-b1.example.invalid").header("X-CSRF-Token","C".repeat(43)).header("Content-Type","application/json");if(key!=null)b.header("Idempotency-Key",key);}var response=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build().send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());evidence.add(Map.of("method",method,"path",path,"status",response.statusCode(),"body",response.body()));assertEquals("private, no-store",response.headers().firstValue("Cache-Control").orElse(""));return response;}
 Map<String,String> business(JdbcTemplate j)throws Exception{var result=new TreeMap<String,String>();for(String table:List.of("meeting","final_confirmation","final_result_review","publication","publication_submission","external_document_mapping","publication_attempt","durable_task","task_attempt","external_operation","external_execution","idempotency_record","audit_event","task_outbox","task_outbox_sequence","task_subject","meeting_search_projection")){var keys=j.queryForList("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION",String.class,table);assertFalse(keys.isEmpty(),"Missing expected table/primary key: "+table);result.put(table,hash(JSON.writeValueAsString(normalize(j.queryForList("SELECT * FROM "+table+" ORDER BY "+String.join(",",keys))))));}return result;}
 static Object normalize(Object value){if(value instanceof Map<?,?> map){var copy=new TreeMap<String,Object>();map.forEach((k,v)->copy.put(k.toString(),normalize(v)));return copy;}if(value instanceof List<?> rows)return rows.stream().map(Task11B1PublicReadsIT::normalize).toList();if(value instanceof java.time.temporal.TemporalAccessor||value instanceof java.util.Date)return value.toString();if(value instanceof byte[] bytes)return Base64.getEncoder().encodeToString(bytes);return value;}
 static String commandDigest(String... values)throws Exception{var bytes=new java.io.ByteArrayOutputStream();var data=new java.io.DataOutputStream(bytes);for(String value:values){byte[] wire=value.getBytes(StandardCharsets.UTF_8);data.writeInt(wire.length);data.write(wire);}return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()));}
 static String hash(String text)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}
 DataSource guard(DataSource original){return (DataSource)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{Object value=invoke(original,m,a);if(!(value instanceof Connection connection))return value;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{Object result=invoke(connection,cm,ca);if(!(result instanceof Statement statement))return result;String prepared=ca!=null&&ca.length>0&&ca[0] instanceof String?(String)ca[0]:null;Class<?> type=statement instanceof PreparedStatement?PreparedStatement.class:Statement.class;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{type},(sp,sm,sa)->{String sql=prepared==null&&sa!=null&&sa.length>0&&sa[0] instanceof String?(String)sa[0]:prepared;if(sm.getName().startsWith("execute")&&sql!=null&&sql.matches("(?is)\\s*(INSERT|UPDATE|DELETE|REPLACE|ALTER|CREATE|DROP).*")){mutationTrace.add(sql);assertTrue(sessionSql.get()&&sql.contains("identity_session"),"Unexpected DB mutation in B1 read-only HTTP window");}return invoke(statement,sm,sa);});});});}
